DROP TABLE IF EXISTS `job_standard_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_standard_profile` (
  `id` int NOT NULL AUTO_INCREMENT,
  `job_info_id` int DEFAULT NULL COMMENT '关联原始 job_info 的 ID',
  `job_name` varchar(255) DEFAULT NULL,
  `city` varchar(50) DEFAULT NULL COMMENT '提取出的城市，如：东莞',
  `clean_industry` varchar(50) DEFAULT NULL COMMENT '提取出的区县，如：虎门镇',
  `min_salary_k` decimal(10,2) DEFAULT NULL COMMENT '统一换算后的最小月薪(K)',
  `max_salary_k` decimal(10,2) DEFAULT NULL COMMENT '统一换算后的最大月薪(K)',
  `salary` varchar(50) DEFAULT NULL,
  `full_detail` longtext COMMENT '纯净的岗位职责描述',
  `pro_score` int DEFAULT '0',
  `inn_score` int DEFAULT '0',
  `lea_score` int DEFAULT '0',
  `str_score` int DEFAULT '0',
  `com_score` int DEFAULT '0',
  `cer_score` int DEFAULT '0',
  `int_score` int DEFAULT '0',
  `dimensions` json DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `industry` varchar(255) DEFAULT NULL,
  `requirements` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4596 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

